"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type SpringPrimitiveProps = ComponentProps<typeof motion.div>;

export function SpringPrimitive({ children, ...props }: SpringPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {x: -48}}
      animate={{x: 48}}
      transition={reduceMotion ? { duration: 0.12 } : { type: "spring", stiffness: 220, damping: 24, mass: 1 }}

    >
      {children}
    </motion.div>
  );
}
